# Comparison methods used in the paper. The C++ competitors (BM13 / LSGraph and JRNS) are
# compiled into this package from the sources shipped in the supplement; their R interfaces are
# generated by Rcpp and documented here. k-lasso is the authors' R code from Example1.R. mSSL is
# an external GitHub package and is wrapped, not vendored.

#' BM13: Bayesian multivariate regression with a decomposable graph (LSGraph)
#'
#' The competitor "BM13" of Niu et al. (2024): the joint high-dimensional Bayesian variable and
#' covariance selection model of Bhadra and Mallick (2013), in the implementation of Niu, Pati
#' and Mallick (2020) distributed as the \code{LSGraph} package inside the supplement. A
#' single decomposable graph (hyper-inverse Wishart prior) is shared by all samples, and the
#' covariates enter as regressors with spike-and-slab selection indicators \code{gamma}.
#' Compiled here from the \code{LSGraph 0.1} sources (Yabo Niu, 2017) with no numerical change.
#'
#' @param Y Response matrix, \code{n x q}.
#' @param X0 Covariate matrix, \code{n x p}.
#' @param bG,DG Hyper-inverse Wishart degrees of freedom and \code{q x q} scale matrix.
#' @param k Number of spline knots for the covariates; \code{0} for a linear regression (the
#'   paper's setting).
#' @param which Knot-placement rule when \code{k > 0}: 0 equally spaced on \code{[m, M]}, 1 on
#'   the range of \code{X0}, 2 per column, 3 user-supplied \code{Kmat}.
#' @param m,M Interval end points for \code{which = 0}.
#' @param Kmat \code{p x k} matrix of knots for \code{which = 3} (any matrix otherwise).
#' @param c Zellner g-prior scale on the regression coefficients.
#' @param alpha Prior inclusion probability of each covariate.
#' @param beta Proposal probability of adding an edge in the graph move.
#' @param gamma0 Initial covariate inclusion indicators (length \code{p}, 0/1).
#' @param Adj0 Initial \code{q x q} adjacency matrix (ones on the diagonal); must be decomposable.
#' @param burnin,nmc Burn-in and kept iterations.
#' @param verbose Print the per-iteration accept/reject messages of the original code.
#' @return A list with \code{accept}, \code{reject}, \code{nondecomp} (move counts),
#'   \code{gamma.map}, \code{gamma.mean}, \code{Adj.map}, \code{Adj.mean} (posterior edge
#'   inclusion frequencies, used for the paper's Figures 6A and 9A) and \code{MAP.like}.
#' @references Bhadra, A. and Mallick, B. K. (2013). Joint high-dimensional Bayesian variable
#'   and covariance selection with an application to eQTL analysis. \emph{Biometrics}, 69(2),
#'   447-457.
#'
#'   Niu, Y., Pati, D. and Mallick, B. K. (2020). Bayesian graph selection consistency under
#'   model misspecification. \emph{Bernoulli}, 27(1), 637-672.
#' @examples
#' \donttest{
#' sim <- simulate_example2(2020)
#' set.seed(2022)
#' fit <- LSGraph(Y = sim$Y, X0 = sim$X, bG = 3, DG = diag(5), k = 0, which = 1, m = 1, M = 1,
#'                Kmat = diag(2), c = 300, alpha = 0.5, beta = 0.5, gamma0 = 0,
#'                Adj0 = diag(5), burnin = 100, nmc = 200, verbose = FALSE)
#' round(fit$Adj.mean, 2)
#' }
#' @name LSGraph
#' @export
NULL

#' Single decomposable-graph sampler from LSGraph
#'
#' Graph-only Metropolis sampler of the \code{LSGraph} package (hyper-inverse Wishart marginal
#' likelihood, decomposable graphs). Returns the maximum a posteriori adjacency among the kept
#' iterations. Compiled from the supplement's \code{LSGraph 0.1} sources.
#'
#' @inheritParams LSGraph
#' @return A list with \code{Adj.est} (MAP adjacency) and \code{MAP.like}.
#' @name MCMCGraph
#' @export
NULL

#' Sample from a hyper-inverse Wishart distribution on a decomposable graph
#'
#' Helpers from the \code{LSGraph} package: \code{HIWsim} draws one covariance and precision
#' matrix pair from the HIW(\code{bG}, \code{DG}) distribution on the decomposable graph
#' \code{Adj}; \code{meanOmegaHIW} returns the posterior mean of the precision matrix.
#'
#' @param Adj Decomposable \code{q x q} adjacency matrix with ones on the diagonal.
#' @param bG,DG Degrees of freedom and scale matrix.
#' @return \code{HIWsim}: a list with \code{Sigma} and \code{Omega}. \code{meanOmegaHIW}: a
#'   \code{q x q} matrix.
#' @name HIWsim
#' @aliases meanOmegaHIW
#' @export meanOmegaHIW
#' @export
NULL

#' JRNS: joint regression and network selection (Samanta, Khare and Michailidis, 2022)
#'
#' The competitor "JRNS" of Niu et al. (2024), used in Example 3 (paper Figure 9C): a
#' spike-and-slab Gibbs sampler for the regression coefficients \code{B} (\code{p x q}) and the
#' error precision matrix \code{Omega} (\code{q x q}) of a multivariate regression
#' \code{Y = X B + E}. Compiled from the three C++ files in \code{JRNS.zip} of the supplement
#' with no numerical change. The authors initialise it from lasso and graphical lasso fits;
#' \code{\link{jrns_initial_values}} reproduces that step.
#'
#' @param B_ini Initial \code{p x q} coefficient matrix.
#' @param Omega_ini Initial \code{q x q} precision matrix.
#' @param Y,X Response (\code{n x q}) and covariate (\code{n x p}) matrices.
#' @param nmc,burnin Kept and burn-in iterations.
#' @param r1,s1 Shape and rate of the gamma prior on the spike-and-slab precision.
#' @param alpha1,beta1,alpha2,beta2 Beta hyperparameters of the inclusion probabilities of
#'   \code{B} and \code{Omega} when \code{hyp = 1}.
#' @param posdef Set to 1 to project \code{Omega} back to positive definiteness when needed.
#' @param hyp Set to 1 to learn the inclusion probabilities.
#' @return A list with the kept draws \code{B} (\code{p x q x (nmc+1)}) and \code{Omega}
#'   (\code{q x q x (nmc+1)}), the running mean \code{Bcumavg}, inclusion counts
#'   \code{Bcount} and \code{Omegacount}, sums \code{Bsum} and \code{Omegasum}, the
#'   median-probability estimates \code{Bhat} and \code{Omegahat}, and the run \code{time}.
#' @references Samanta, S., Khare, K. and Michailidis, G. (2022). A generalized likelihood-based
#'   Bayesian approach for scalable joint regression and covariance selection in high
#'   dimensions. \emph{Statistics and Computing}, 32, 47.
#' @seealso \code{\link{StepB}}, \code{\link{StepOmega}}, \code{\link{jrns_initial_values}}
#' @name JRNS
#' @export
NULL

#' JRNS component samplers
#'
#' The two conditional samplers distributed with JRNS: \code{StepB} updates the regression
#' coefficients given residual variances, \code{StepOmega} updates the precision matrix given
#' a residual scatter matrix \code{S}. Compiled from the supplement with no numerical change.
#'
#' @inheritParams JRNS
#' @param sigma2_ini Initial residual variances (length \code{q}) for \code{StepB}.
#' @param S Residual scatter matrix for \code{StepOmega}.
#' @param temp Initial precision matrix for \code{StepOmega}.
#' @param n Sample size used by \code{StepOmega}.
#' @param r,s Gamma hyperparameters (named \code{r1}, \code{s1} in \code{JRNS}).
#' @return Lists of draws, counts and estimates as in \code{\link{JRNS}}.
#' @name StepB
#' @aliases StepOmega
#' @export StepOmega
#' @export
NULL

#' Lasso and graphical-lasso starting values for JRNS
#'
#' Reproduces the initialisation block of the authors' \code{Example3.R}: one cross-validated
#' lasso per response column (\code{glmnet}, \code{lambda.1se}, no intercept, no
#' standardisation) gives \code{B}, and a graphical lasso on the residual covariance with
#' penalty \code{sqrt(log(p)/n)} gives \code{Omega}. Requires the suggested packages
#' \pkg{glmnet} and \pkg{glasso}.
#'
#' @param X,Y Covariate (\code{n x p}) and response (\code{n x q}) matrices.
#' @return A list with \code{B} (\code{p x q}) and \code{Omega} (\code{q x q}).
#' @export
jrns_initial_values <- function(X, Y) {
  if (!requireNamespace("glmnet", quietly = TRUE) || !requireNamespace("glasso", quietly = TRUE))
    stop("jrns_initial_values() needs the packages 'glmnet' and 'glasso'.")
  n <- nrow(Y); p <- ncol(X); q <- ncol(Y)
  B <- matrix(0, p, q)
  for (i in seq_len(q)) {
    cv <- glmnet::cv.glmnet(X, Y[, i])
    m <- glmnet::glmnet(X, Y[, i], alpha = 1, family = "gaussian", lambda = cv$lambda.1se,
                        intercept = FALSE, standardize = FALSE)
    B[, i] <- as.vector(m$beta)
  }
  er <- Y - X %*% B
  s0 <- crossprod(er) / n
  Omega <- glasso::glasso(s = s0, rho = sqrt(log(p) / n))$wi
  list(B = B, Omega = Omega)
}

#' Posterior edge inclusion frequencies from JRNS draws
#'
#' The authors summarise the JRNS output by the proportion of kept precision-matrix draws in
#' which each off-diagonal entry is non-zero (paper Figure 9C). This helper does that.
#'
#' @param fit A list returned by \code{\link{JRNS}}.
#' @return A \code{q x q} matrix of inclusion frequencies with zero diagonal.
#' @export
jrns_edge_frequencies <- function(fit) {
  O <- fit$Omega
  S <- apply(O != 0, c(1, 2), mean)
  diag(S) <- 0
  S
}

#' k-lasso: kernel-smoothed graphical lasso (Example 1 competitor)
#'
#' The "k-lasso" competitor of Section 4.1 of Niu et al. (2024), taken from the authors'
#' \code{Example1.R}: for each sample, the covariance of \code{Y} is estimated by Gaussian
#' kernel weights in covariate space (\code{\link{kernel_mc}}) and a graphical lasso
#' (\pkg{huge}) is fitted to it, with the bandwidth and penalty chosen on an AIC grid.
#' Returns one precision matrix per sample. The paper reports that this took about 100
#' minutes for 300 samples and 3 nodes; the loop is the authors' and is left unoptimised.
#'
#' One compatibility change in this wrapper: current versions of \pkg{huge} require the
#' penalty sequence to be non-increasing and stop with an error on the authors' increasing
#' grid, so the grid is sorted in decreasing order before the call. The set of penalties, and
#' hence the AIC choice, is the same; to run the grid in the original order install a
#' \pkg{huge} version before 1.3.5.
#'
#' @param Y Response matrix, \code{n x q}.
#' @param X Covariate matrix, \code{n x p}.
#' @param h_grid,l_grid Bandwidth and penalty grids (the paper uses 20 values of each on
#'   \code{[0.1, 1]}).
#' @param verbose Print progress every 10 samples.
#' @return An array of dimension \code{q x q x n} of precision-matrix estimates.
#' @references Liu, H., Chen, X., Wasserman, L. and Lafferty, J. (2010). Graph-valued
#'   regression. \emph{Advances in Neural Information Processing Systems}, 23.
#' @export
klasso <- function(Y, X, h_grid = seq(0.1, 1, length.out = 20), l_grid = seq(0.1, 1, length.out = 20),
                   verbose = TRUE) {
  if (!requireNamespace("huge", quietly = TRUE)) stop("klasso() needs the package 'huge'.")
  n <- nrow(Y); q <- ncol(Y); nh <- length(h_grid); nl <- length(l_grid)
  lam <- sort(l_grid, decreasing = TRUE)   # huge >= 1.3.5 requires a non-increasing sequence
  Omega_est <- array(0, c(q, q, n))
  aic <- matrix(0, nh, nl)
  for (i in seq_len(n)) {
    if (verbose && i %% 10 == 0) message("k-lasso sample ", i, " of ", n)
    for (j in seq_len(nh)) {
      r <- kernel_mc(Y, X, h = h_grid[j])
      gl <- huge::huge(r$Sig[i, , ], lambda = lam, method = "glasso", verbose = FALSE)
      aic[j, ] <- -2 * gl$loglik + 2 * gl$df
    }
    lmid <- arrayInd(which.min(aic), c(nh, nl))
    r <- kernel_mc(Y, X, h = h_grid[lmid[1]])
    gl <- huge::huge(r$Sig[i, , ], lambda = lam[lmid[2]], method = "glasso", verbose = FALSE)
    Omega_est[, , i] <- as.matrix(gl$icov[[1]])
  }
  Omega_est
}

#' Gaussian kernel weight between two covariate vectors
#'
#' Authors' helper from \code{Example1.R}: \code{dnorm(||y - x|| / h)}.
#' @param y,x Numeric vectors.
#' @param h Bandwidth.
#' @return A scalar weight.
#' @export
ekernel <- function(y, x, h) {
  stats::dnorm(sqrt(sum((y - x)^2)) / h)
}

#' Kernel-weighted mean and covariance of Y at covariate values e
#'
#' Authors' helper from \code{Example1.R}: for each row of \code{e}, the Nadaraya-Watson
#' weighted mean and covariance of \code{y} with weights \code{\link{ekernel}} on the rows of
#' \code{x}.
#' @param y Response matrix, \code{n x p}.
#' @param x Covariate matrix, \code{n x q}.
#' @param e Evaluation points, \code{m x q}; default \code{x}.
#' @param h Bandwidth.
#' @return A list with \code{mu} (\code{m x p}) and \code{Sig} (\code{m x p x p}).
#' @export
kernel_mc <- function(y, x, e = x, h = 1) {
  n <- nrow(y); m <- nrow(e); p <- ncol(y)
  mu <- matrix(0, m, p)
  Sig <- array(0, c(m, p, p))
  for (i in 1:m) {
    tmp <- 0
    for (j in 1:n) {
      mu[i, ] <- mu[i, ] + ekernel(e[i, ], x[j, ], h) * y[j, ]
      tmp <- tmp + ekernel(e[i, ], x[j, ], h)
    }
    mu[i, ] <- mu[i, ] / tmp
    for (j in 1:n) {
      Sig[i, , ] <- Sig[i, , ] + ekernel(e[i, ], x[j, ], h) * (y[j, ] - mu[i, ]) %*% t(y[j, ] - mu[i, ])
    }
    Sig[i, , ] <- Sig[i, , ] / tmp
  }
  list(mu = mu, Sig = Sig)
}

#' mSSL: multivariate spike-and-slab lasso (external package)
#'
#' The "mSSL" competitor of Examples 2 and 3 (Deshpande, Rockova and George, 2019) lives in
#' the GitHub package \code{skdeshpande91/multivariate_SSL/mSSL}, which is not on CRAN and is
#' therefore not vendored here and not declared as a dependency (\code{\link{has_mSSL}} tests for
#' it at run time). This wrapper calls \code{mSSL_dpe(X, Y)} of that package exactly as the
#' authors' scripts do and returns the absolute partial correlations and the implied graph,
#' which is what the paper's Figures 6B and 9B display. Install the package with
#' \code{remotes::install_github("skdeshpande91/multivariate_SSL", subdir = "mSSL")}.
#'
#' @param X,Y Covariate and response matrices.
#' @param ... Passed to \code{mSSL_dpe}.
#' @return A list with the \code{mSSL_dpe} fit, \code{Omega} (estimated precision),
#'   \code{abs_partial_cor} and the 0/1 \code{adj} of non-zero entries.
#' @references Deshpande, S. K., Rockova, V. and George, E. I. (2019). Simultaneous variable and
#'   covariance selection with the multivariate spike-and-slab lasso. \emph{Journal of
#'   Computational and Graphical Statistics}, 28(4), 921-931.
#' @export
fit_mSSL <- function(X, Y, ...) {
  if (!has_mSSL())
    stop("fit_mSSL() needs the GitHub package 'mSSL': ",
         "remotes::install_github(\"skdeshpande91/multivariate_SSL\", subdir = \"mSSL\")")
  mSSL_dpe <- get("mSSL_dpe", envir = asNamespace("mSSL"))
  fit <- mSSL_dpe(X, Y, ...)
  Om <- fit$Omega
  q <- ncol(Om)
  pc <- Om
  for (i in seq_len(q)) for (j in seq_len(q)) pc[i, j] <- pc[j, i] <- Om[i, j] / sqrt(Om[i, i] * Om[j, j])
  pc <- abs(pc)
  adj <- (pc > 0) * 1; diag(adj) <- 0
  list(fit = fit, Omega = Om, abs_partial_cor = pc, adj = adj)
}

#' Is the optional mSSL package installed?
#'
#' The mSSL competitor is distributed on GitHub only, so it is not listed among this package's
#' dependencies (CRAN-style dependency resolution cannot find it); this helper checks for it at
#' run time. Install it with
#' \code{remotes::install_github("skdeshpande91/multivariate_SSL", subdir = "mSSL")}.
#' @return \code{TRUE} or \code{FALSE}.
#' @export
has_mSSL <- function() {
  pkg <- "mSSL"
  requireNamespace(pkg, quietly = TRUE)
}
